import { isDeepStrictEqual, } from 'node:util';
import { ProducerInputRunError, } from './producer-input-error.ts';
import { PRODUCER_INPUT_PATHS, } from './producer-input-paths.ts';

//region Fixed host-to-child primitive bindings

/**
 * Hostname conveys the operation, never the caller's machine identity.
 */
export const PRODUCER_INPUT_HOSTNAME = 'producer-preparation-input';
/**
 * Bound primitive fields are not an approval certificate or arbitrary environment map.
 */
export type ProducerInputChildIdentity = {
  /**
   * Exclusive namespace identity generated by the host.
   */
  readonly runId: string;
  /**
   * Independently recorded raw launch identity.
   */
  readonly launchSha256: string;
  /**
   * Independently recorded raw launch extent.
   */
  readonly launchBytes: number;
  /**
   * Caller UID preserved by the declared namespace mapping.
   */
  readonly callerUid: number;
  /**
   * Caller GID is checked separately rather than assumed equal to UID.
   */
  readonly callerGid: number;
};
/** Leading UUID group width. */
const UUID_LEADING_WIDTH = 8;
/** Interior UUID group width, including version and variant groups. */
const UUID_INTERIOR_WIDTH = 4;
/** Trailing UUID group width. */
const UUID_TRAILING_WIDTH = 12;
/**
 * Fixed grammars keep identity checks independent from supplied contents.
 */
const IDENTITY_WIDTHS = {
  sha256: 64,
  uuid: [
    UUID_LEADING_WIDTH,
    UUID_INTERIOR_WIDTH,
    UUID_INTERIOR_WIDTH,
    UUID_INTERIOR_WIDTH,
    UUID_TRAILING_WIDTH
  ],
} as const;

/**
 * Constructs the complete child environment rather than inheriting host or image entries.
 *
 * @param identity - owned host identity and independent launch metadata
 *
 * @returns Fixed vocabulary and exact values expected before application import
 *
 * @example
 * ```ts
 * const environment = producerInputChildEnvironment(identity);
 * ```
 */
export function producerInputChildEnvironment(identity: ProducerInputChildIdentity): Readonly<Record<string, string>> {
  return {
    PATH: '/usr/bin:/bin',
    HOME: PRODUCER_INPUT_PATHS.home,
    HOSTNAME: PRODUCER_INPUT_HOSTNAME,
    TMPDIR: '/tmp',
    XDG_CONFIG_HOME: `${PRODUCER_INPUT_PATHS.home}/.config`,
    XDG_CACHE_HOME: `${PRODUCER_INPUT_PATHS.home}/.cache`,
    XDG_DATA_HOME: `${PRODUCER_INPUT_PATHS.home}/.local/share`,
    GIT_CONFIG_NOSYSTEM: '1',
    GIT_CONFIG_GLOBAL: '/dev/null',
    GIT_TERMINAL_PROMPT: '0',
    PREPARATION_INPUT_RUN_ID: identity.runId,
    PREPARATION_LAUNCH_SHA: identity.launchSha256,
    PREPARATION_LAUNCH_BYTES: String(identity.launchBytes),
    PREPARATION_CALLER_UID: String(identity.callerUid),
    PREPARATION_CALLER_GID: String(identity.callerGid),
  };
}

/**
 * Checks fixed-width ASCII identity without a Unicode or regular-expression reinterpretation.
 *
 * @param value - candidate primitive string
 *
 * @param length - owning identity domain width
 *
 * @returns Whether every code unit has the canonical lowercase hexadecimal spelling
 *
 * @example
 * ```ts
 * const valid = lowerHex({ value, length: 64 });
 * ```
 */
function lowerHex({
  value,
  length,
}: {
  readonly value: unknown;
  readonly length: number
},): boolean {
  if (((typeof value) !== 'string') || (value.length !== length))
    return false;
  for (let index = 0; index < value.length; index += 1) {
    if (!'0123456789abcdef'.includes(value.charAt(index)))
      return false;
  }
  return true;
}

/**
 * Reads only a canonical UUIDv4 namespace ID, not a correspondence-attempt marker.
 *
 * @param value - untrusted inherited field
 *
 * @returns Original canonical UUID spelling
 *
 * @throws ProducerInputRunError when namespace grammar differs
 *
 * @example
 * ```ts
 * const runId = childRunId(value);
 * ```
 */
function childRunId(value: unknown): string {
  if ((typeof value) !== 'string')
    throw new ProducerInputRunError({
      operation: 'verify-runtime',
      locator: 'child run identity',
    });
  /**
   * Group extents do not establish version or variant by themselves.
   */
  const parts = value.split('-');
  /**
   * Version and RFC variant are checked independently after the complete group spelling.
   */
  const [, , version, variant] = parts;
  if ((parts.length
    !== IDENTITY_WIDTHS.uuid
    .length) || (!IDENTITY_WIDTHS.uuid
      .every(function group(
        length,
        index
      ): boolean {
    return lowerHex({
      value: parts[index],
      length
    });
  }))
    || (version === undefined)
    || (!version.startsWith('4'))
    || (variant === undefined)
    || (!'89ab'.includes(variant.charAt(0))))
    throw new ProducerInputRunError({
      operation: 'verify-runtime',
      locator: 'child run identity',
    });
  return value;
}

/**
 * Reads an exact nonnegative decimal field without rounding or accepting alternate spellings.
 *
 * @param value - inherited field to validate
 *
 * @param positive - launch extent must be nonempty while UID/GID may be zero
 *
 * @param locator - fixed affected field label
 *
 * @returns Canonical integer value
 *
 * @throws ProducerInputRunError when field shape or extent differs
 *
 * @example
 * ```ts
 * const uid = childInteger({ value, positive: false, locator: 'child UID' });
 * ```
 */
function childInteger({
  value,
  positive,
  locator,
}: {
  readonly value: unknown;
  readonly positive: boolean;
  readonly locator: string
},): number {
  if ((typeof value) !== 'string')
    throw new ProducerInputRunError({
      operation: 'verify-runtime',
      locator,
    });
  /**
   * Number conversion alone would admit blanks, exponent notation and rounded extents.
   */
  const result = Number(value);
  if ((!Number.isSafeInteger(result)) || (result < 0)
    || (positive && (result === 0))
    || (String(result) !== value))
    throw new ProducerInputRunError({
      operation: 'verify-runtime',
      locator,
    });
  return result;
}

/**
 * Owns and checks the exact child environment before any application module is imported.
 * Trusted host startup remains responsible for preventing preloads before this JavaScript executes.
 *
 * @returns Canonical primitive host bindings after complete environment equality
 *
 * @throws ProducerInputRunError when identity, an expected value or any extra entry differs
 *
 * @example
 * ```ts
 * const identity = readProducerInputChildEnvironment();
 * ```
 */
export function readProducerInputChildEnvironment(): ProducerInputChildIdentity {
  /**
   * Native environment values are copied without exposing them in errors or logs.
   */
  const observed = Object.fromEntries(Object.entries(process.env));
  /**
   * Raw launch identity must be canonical before it receives file-read authority.
   */
  const launchSha256 = observed.PREPARATION_LAUNCH_SHA;
  if (((typeof launchSha256) !== 'string') || (!lowerHex({
    value: launchSha256,
    length: IDENTITY_WIDTHS.sha256
  })))
    throw new ProducerInputRunError({
      operation: 'verify-runtime',
      locator: 'child launch identity',
    });
  /**
   * Every independently meaningful field is validated before comparing the complete environment.
   */
  const identity: ProducerInputChildIdentity = {
    runId: childRunId(observed.PREPARATION_INPUT_RUN_ID),
    launchSha256,
    launchBytes: childInteger({
      value: observed.PREPARATION_LAUNCH_BYTES,
      positive: true,
      locator: 'child launch extent'
    }),
    callerUid: childInteger({
      value: observed.PREPARATION_CALLER_UID,
      positive: false,
      locator: 'child UID'
    }),
    callerGid: childInteger({
      value: observed.PREPARATION_CALLER_GID,
      positive: false,
      locator: 'child GID'
    }),
  };
  if (!isDeepStrictEqual(
    observed,
    producerInputChildEnvironment(identity)
  ))
    throw new ProducerInputRunError({
      operation: 'verify-runtime',
      locator: 'child environment',
    });
  return identity;
}

//endregion Fixed host-to-child primitive bindings
